export interface PipedriveWebhookPayload {
  meta: {
    action: string;
    entity: string;
    entity_id: string;
    timestamp: string;
    version: string;
    webhook_id: string;
    webhook_owner_id: string;
    attempt: number;
    host: string;
  };
  data: {
    id: number;
    title: string;
    value: number | string;
    currency: string;
    owner_id: number;
    owner_name: string;
    owner_email: string;
    close_date: string;
    stage_id: number;
    status: string;
    add_time: string;
    update_time: string;
    custom_fields: Record<string, unknown>;
  };
  previous: null | Record<string, unknown>;
}

export interface ConnectorConfig {
  notionApiKey: string;
  signedDatabaseId: string;
  ownerEmailToNotionUserId: Record<string, string>;
  fetch?: typeof fetch;
}

export interface HandleResult {
  notionPageId: string;
}

function validatePayload(payload: PipedriveWebhookPayload): void {
  if (!payload.meta || payload.meta.action !== 'change') {
    throw new Error('Invalid webhook: meta.action must be "change"');
  }
  if (payload.meta.entity !== 'deal') {
    throw new Error('Invalid webhook: meta.entity must be "deal"');
  }
  if (!payload.data || payload.data.status !== 'won') {
    throw new Error('Invalid webhook: data.status must be "won"');
  }
  if (!payload.data.title) {
    throw new Error('Missing required field: data.title');
  }
  if (payload.data.value === undefined || payload.data.value === null) {
    throw new Error('Missing required field: data.value');
  }
  if (!payload.data.close_date) {
    throw new Error('Missing required field: data.close_date');
  }
  if (!payload.data.owner_email) {
    throw new Error('Missing required field: data.owner_email');
  }
}

function formatValue(value: number | string, currency: string): string {
  return `${value} ${currency}`;
}

function buildNotionProperties(
  payload: PipedriveWebhookPayload,
  ownerEmailToNotionUserId: Record<string, string>
): Record<string, unknown> {
  const ownerEmail = payload.data.owner_email;
  const notionUserId = ownerEmailToNotionUserId[ownerEmail];
  if (!notionUserId) {
    throw new Error(`No Notion user ID mapping for owner email: ${ownerEmail}`);
  }

  return {
    'Deal Title': {
      title: [
        {
          text: {
            content: payload.data.title,
          },
        },
      ],
    },
    'Deal Value': {
      rich_text: [
        {
          text: {
            content: formatValue(payload.data.value, payload.data.currency),
          },
        },
      ],
    },
    Owner: {
      people: [
        {
          object: 'user',
          id: notionUserId,
        },
      ],
    },
    'Close Date': {
      date: {
        start: payload.data.close_date,
      },
    },
  };
}

export async function handle(
  payload: PipedriveWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload);

  const fetchImpl = config.fetch ?? fetch;
  const properties = buildNotionProperties(payload, config.ownerEmailToNotionUserId);

  const body = {
    parent: {
      type: 'database_id',
      database_id: config.signedDatabaseId,
    },
    properties,
  };

  const response = await fetchImpl('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.notionApiKey}`,
      'Notion-Version': '2022-06-28',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    throw new Error(
      `Notion API error: ${response.status} ${response.statusText} for POST https://api.notion.com/v1/pages - ${errorText}`
    );
  }

  const result = (await response.json()) as { id: string };
  return { notionPageId: result.id };
}

